import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_pooled_conversion_rate_equal_groups():
    groups = {"a": [{"converted": True}, {"converted": False}], "b": [{"converted": True}, {"converted": False}]}
    assert pooled_conversion_rate(groups) == 0.5


def test_parse_session_log_one_line():
    assert parse_session_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "converted": True}]


def test_campaign_summary_basic():
    e = [{"id": "a", "day": 1, "converted": True}, {"id": "b", "day": 2, "converted": False}]
    assert campaign_summary({"g": e}, 1)["groups"] == 1


def test_conversion_rate_counts_none_in_denominator():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "small": [{"converted": True}],
        "large": [{"converted": False}] * 3,
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0


@pytest.mark.parametrize(("days", "expected"), [(0, 0), (2, 5), (5, 6)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected


def test_parse_session_log_skips_blank_and_comment_lines_and_maps_flags():
    sessions = parse_session_log(["", " \t\n", "  # comment", " a , 1 , 1 ", "b,2,0", "c,3,  "])
    assert [e["id"] for e in sessions] == ["a", "b", "c"]
    assert [e["day"] for e in sessions] == [1, 2, 3]
    assert sessions[0]["converted"] is True
    assert sessions[1]["converted"] is False
    assert sessions[2]["converted"] is None


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,not-a-day,0"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 3\b"):
        parse_session_log(["", "  # comment", bad_line])


def test_dedupe_sessions_keeps_last_record_and_sorts_by_day_then_id():
    events = parse_session_log(["b,9,1", "c,3,1", "b,3,0", "a,3,1", "z,2,1"])
    assert dedupe_sessions(events) == [events[4], events[3], events[2], events[1]]


def test_daily_conversion_counts_fills_gaps_and_ignores_out_of_range_sessions():
    events = parse_session_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,2,", "f,3,1", "g,4,1"])
    assert daily_conversion_counts(events, 1, 3) == [2, 0, 1]
    assert daily_conversion_counts(events, 3, 1) == []


def test_campaign_summary_uses_calendar_days_and_counts_nonempty_groups():
    groups = {
        "early": parse_session_log(["a,1,1"]),
        "late": parse_session_log(["b,4,0", "c,4,"]),
        "empty": [],
    }
    assert campaign_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 4) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert campaign_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_groups_and_breaks_ties_by_name():
    groups = {
        "z": [{"converted": True}],
        "b": [{"converted": False}],
        "empty": [],
        "a": [{"converted": True}],
    }
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 5) == ["a", "z", "b"]


def test_conversion_rate_by_group_sorts_names_and_maps_empty_to_none():
    rates = conversion_rate_by_group({"z": [{"converted": False}], "a": []})
    assert list(rates.items()) == [("a", None), ("z", 0.0)]


@pytest.mark.parametrize(("counts", "expected"), [([1, 0, 1, 1, -1, 1], 2), ([-1, 0], 0), ([], 0)])
def test_longest_conversion_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected

